WITH store_sales_agg AS (SELECT ss_store_sk, ss_sold_date_sk, SUM(ss_net_paid_inc_tax) AS total_net_paid, SUM(ss_net_profit) AS total_net_profit, COUNT(DISTINCT ss_customer_sk) AS distinct_customers FROM store_sales GROUP BY ss_store_sk, ss_sold_date_sk), customer_store_map AS (SELECT DISTINCT ss_customer_sk, ss_store_sk FROM store_sales), customer_returns AS (SELECT wr_refunded_customer_sk AS customer_sk, SUM(wr_return_amt_inc_tax) AS total_return_amount, SUM(wr_net_loss) AS total_net_loss FROM web_returns GROUP BY wr_refunded_customer_sk), store_returns AS (SELECT csm.ss_store_sk, cr.total_return_amount, cr.total_net_loss FROM customer_store_map csm JOIN customer_returns cr ON csm.ss_customer_sk = cr.customer_sk), store_reason_agg_base AS (SELECT csm.ss_store_sk, wr.wr_reason_sk, SUM(wr.wr_return_amt_inc_tax) AS reason_return_amount FROM customer_store_map csm JOIN web_returns wr ON csm.ss_customer_sk = wr.wr_refunded_customer_sk GROUP BY csm.ss_store_sk, wr.wr_reason_sk), store_reason_agg AS (SELECT ss_store_sk, wr_reason_sk, reason_return_amount, ROW_NUMBER() OVER (PARTITION BY ss_store_sk ORDER BY reason_return_amount DESC) AS rn FROM store_reason_agg_base) SELECT ss.ss_store_sk, ss.ss_sold_date_sk, ss.total_net_paid, ss.total_net_profit, ss.distinct_customers, COALESCE(sr.total_return_amount, 0) AS total_return_amount, COALESCE(sr.total_net_loss, 0) AS total_net_loss, COALESCE(rt.r_reason_desc, 'No Returns') AS top_return_reason, CASE WHEN ss.total_net_profit > 0 AND COALESCE(sr.total_return_amount, 0) > 0 THEN ss.total_net_profit / sr.total_return_amount ELSE NULL END AS profit_to_return_ratio, LAG(ss.total_net_paid) OVER (PARTITION BY ss.ss_store_sk ORDER BY ss.ss_sold_date_sk) AS previous_net_paid, ss.total_net_paid - LAG(ss.total_net_paid) OVER (PARTITION BY ss.ss_store_sk ORDER BY ss.ss_sold_date_sk) AS net_paid_change, RANK() OVER (PARTITION BY ss.ss_sold_date_sk ORDER BY ss.total_net_paid DESC) AS store_sales_rank FROM store_sales_agg ss LEFT JOIN store_returns sr ON ss.ss_store_sk = sr.ss_store_sk LEFT JOIN (SELECT ss_store_sk, wr_reason_sk FROM store_reason_agg WHERE rn = 1) sr_top ON ss.ss_store_sk = sr_top.ss_store_sk LEFT JOIN reason rt ON sr_top.wr_reason_sk = rt.r_reason_sk ORDER BY ss.ss_sold_date_sk, store_sales_rank
